const body = $input.first().json.body || $input.first().json;
const keyword = body.keyword || body.query || body.category;
const location = body.location || body.base_location;
const maxResults = Number(body.max_results || body.limit || 25);

if (!keyword || !location) {
  throw new Error('Send keyword and location, for example: { \"keyword\": \"roofing contractors\", \"location\": \"Austin, TX\" }.');
}

return [{ json: { keyword, location, max_results: maxResults, timestamp: new Date().toISOString() } }];

const response = $input.first().json;
if (response.code !== 0) {
  return [{ json: { status: 'error', message: response.message || 'CoreClaw request failed', request_id: response.request_id || '' } }];
}

const leads = response.data?.list || response.data?.items || [];
return leads.map((lead) => ({
  json: {
    name: lead.name || lead.title || '',
    category: lead.category || '',
    address: lead.address || lead.formatted_address || '',
    phone: lead.phone || lead.phone_number || '',
    website: lead.website || '',
    rating: lead.rating || 0,
    review_count: lead.reviews || lead.review_count || 0,
    maps_url: lead.maps_url || lead.url || ''
  }
}));

